/// kcal burned = MET x weight(kg) x minutes / 60.
int burnKcal(double met, double weightKg, int minutes) =>
    (met * weightKg * minutes / 60).round();

/// Minutes needed to burn [kcal] at a given MET and weight.
int burnMinutes(double met, double weightKg, int kcal) =>
    (kcal / (met * weightKg / 60)).round().clamp(1, 1 << 30);

/// Calories burned from an activity record: steps + exercise minutes.
/// Steps use the web app's formula: steps x 0.04 x (weight / 70).
({int stepsKcal, int exKcal, int total}) activityKcal({
  required int steps,
  required int exerciseType,
  required int minutes,
  required double weightKg,
}) {
  final stepsKcal = (steps * 0.04 * (weightKg / 70)).round();
  final met = (exerciseType >= 0 && exerciseType < exerciseBurn.length)
      ? exerciseBurn[exerciseType].met
      : exerciseBurn[1].met;
  final exKcal = burnKcal(met, weightKg, minutes);
  return (stepsKcal: stepsKcal, exKcal: exKcal, total: stepsKcal + exKcal);
}
